def range_version(primitive: RangePrimitive, definition: RangeDefinition, *, prior_scale: PriorScale | None = None,
                  cut: int | None = None) -> RangeVersion:
    primitive_registry_links(primitive)  # Reject a detached/altered primitive.
    if type(definition) is not RangeDefinition:
        raise ContractError("registered immutable range definition required")
    selection = primitive.selection
    if (definition.calendar_version != selection.session.version
            or definition.clock_variant_id != selection.window.clock_variant
            or definition.raw_instrument_definition != primitive.instrument.definition_version
            or definition.trading_date != selection.window.trading_date
            or (definition.formation_start, definition.formation_end) != (primitive.formation_start, primitive.formation_end)):
        raise ContractError("range definition substituted another clock or raw instrument")
    if definition.geometry_kind != "wick":
        raise DependencyUnavailable("non-wick source formula requires its own registered adapter")
    available_at = max(primitive.published_at, selection.selected_at, selection.session.known_at,
                       selection.interval_graph.known_at)
    at = available_at if cut is None else timestamp(cut)
    if at < available_at:
        raise DependencyUnavailable("range source unavailable at requested cut")
    geometry = (RangeArithmetic(primitive.low_ticks, primitive.high_ticks, primitive.open_ticks, primitive.close_ticks)
                if primitive.supports("high", "low") else None)
    o, h, l, c = primitive.observed_ohlc
    diagnostic = RangeArithmetic(l, h, o, c) if h is not None and l is not None else None
    scale_id, normalized = None, None
    if prior_scale is not None:
        if type(prior_scale) is not PriorScale:
            raise ContractError("prior normalization scale needs typed lineage")
        scale_id = prior_scale.id
        if (geometry is not None and prior_scale.complete and prior_scale.value_ticks > 0
                and prior_scale.formation_end <= primitive.formation_start and prior_scale.published_at <= at):
            normalized = geometry.width / prior_scale.value_ticks
    identity = "c01-range:" + digest((primitive.id, definition.identity))
    version_id = "c01-version:" + digest((identity, primitive.version_id, prior_scale, normalized, at))
    value = RangeVersion(identity, version_id, definition, primitive, geometry, diagnostic, scale_id, normalized, at)
    object.__setattr__(value, '_receipt', (_RANGE_TOKEN, prior_scale, at, _range_record(value)))
    return value


def _range_record(value):
    return digest((value.id, value.version_id, value.definition, value.primitive.record(),
                   value.geometry, value.diagnostic_geometry, value.prior_scale_id,
                   value.width_prior_volatility, value.derivation_at))


def validate_range_version(value):
    if type(value) is not RangeVersion:
        raise ContractError('actual range formula result required')
    receipt = value._receipt
    if (type(receipt) is not tuple or len(receipt) != 4 or receipt[0] is not _RANGE_TOKEN
            or receipt[3] != _range_record(value)):
        raise ContractError('range formula result lacks its unaltered factory receipt')
    rebuilt = range_version(value.primitive, value.definition, prior_scale=receipt[1], cut=receipt[2])
    if _range_record(rebuilt) != receipt[3]:
        raise IntegrityError('range result differs from its retained formula')
    return value


def range_object_member(value: RangeVersion, links: RangeRegistryLinks, *, known_at: int,
                        previous: ObjectRevision | None = None) -> DerivedRangeMember:
    validate_range_version(value)
    _require_links(links, value.primitive)
    if links.primitive_version != value.primitive.version_id:
        raise ContractError("range object needs exact measured version and registry links")
    # Diagnostic provisional/incomplete geometry can be retained, never eligible.
    geometry = value.geometry if value.geometry is not None else value.diagnostic_geometry
    if geometry is None:
        raise DependencyUnavailable("empty range has no fabricated geometric extent")
    timestamp(known_at)
    if known_at < value.known_at:
        raise DependencyUnavailable("range object precedes its source publication")
    birth = BirthKey(GENERATOR, GENERATOR_DEFINITION, value.primitive.instrument, (),

def edge_extensions(primitive, *, ratios=(Fraction(1, 2), Fraction(1)),
                    contact_tolerance=Fraction(1), clocks, horizon_end,
                    candidate_cap=256, regions=False):
    require_primitive(primitive, clocks=clocks, horizon_end=horizon_end)
    _bound(candidate_cap); _exact(contact_tolerance)
    if (type(ratios) is not tuple or not ratios or len(ratios) > 128
            or any(type(r) is not Fraction or r <= 0 for r in ratios)
            or len(set(ratios)) != len(ratios) or type(regions) is not bool
            or contact_tolerance < 0):
        raise ContractError('bounded distinct exact positive edge ratios required')
    count = 2 if regions else 2 * len(ratios)
    if regions and (len(ratios) != 2 or ratios[0] >= ratios[1]):
        raise ContractError('a region requires exactly two ascending edge ratios')
    if count > candidate_cap:
        raise ContractError('candidate cap exceeded before source publication')
    support = {f.field: f.status for f in primitive.field_support}
    base = (primitive, GENERATOR, DEFINITION)
    tail = (clocks, horizon_end)
    recipe = dict(primitive=primitive, ratios=ratios, contact_tolerance=contact_tolerance,
                  clocks=clocks, horizon_end=horizon_end, candidate_cap=candidate_cap, regions=regions)
    def result(locations, status):
        return _seal_locations(LocationSet(*base, locations, *tail, status, candidate_cap, 'edge'),
                               edge_extensions, recipe)
    if any(support[f] != 'observed' for f in ('high', 'low')):
        return result((), 'unavailable_required_fields')
    low, high = Fraction(primitive.low_ticks), Fraction(primitive.high_ticks)
    width = high - low
    if width < 0:
        raise ContractError('inverted certified range')
    if width == 0:
        return result((), 'unavailable_zero_width')
    definition = 'def:' + content_hash((GENERATOR, DEFINITION, ratios, contact_tolerance,
                                      'edge_distance', regions))
    output = []
    for side, edge in (('upper', high), ('lower', low)):
        sign = 1 if side == 'upper' else -1
        prices = tuple(edge + sign * ratio * width for ratio in ratios)
        if regions:
            lower, upper = min(prices), max(prices)
            raw = primitive.selection.instrument.raw_symbol
            geometry = Geometry(lower, upper, lower - contact_tolerance, upper + contact_tolerance,
                                definition, raw, raw, entry_tolerance=contact_tolerance,
                                preset_ratios=ratios)
            output.append(Location(side + '_edge_region', ratios, geometry, ('high', 'low')))
        else:
            for ratio, price in zip(ratios, prices):
                output.append(Location(side + '_edge_extension', (ratio,),
                                       line_geometry(primitive, price=price,
                                                     tolerance=contact_tolerance,
                                                     definition=definition, ratios=(ratio,)),
                                       ('high', 'low')))
    return result(tuple(output), 'observed')

def prior_locations(primitive, *, clocks, horizon_end, fields=FIELDS,
                    contact_tolerance=Fraction(1), candidate_cap=256,
                    prior_selection=None, current_instrument=None, semantic='prior_RTH'):
    require_primitive(primitive, clocks=clocks, horizon_end=horizon_end)
    _bound(candidate_cap); _exact(contact_tolerance)
    if (type(fields) is not tuple or not fields or len(set(fields)) != len(fields)
            or any(f not in FIELDS for f in fields) or contact_tolerance < 0
            or semantic not in ('prior_RTH', 'full_session', 'current_range')):
        raise ContractError('explicit finite OHLC subset and source interpretation required')
    if len(fields) > candidate_cap:
        raise ContractError('prior candidate cap exceeded before mutation')
    if (prior_selection is None) != (current_instrument is None):
        raise ContractError('prior selection and current raw instrument must be bound together')
    if semantic == 'prior_RTH' and prior_selection is None:
        raise ContractError('prior_RTH requires actual calendar predecessor selection')
    if prior_selection is not None:
        require_prior_primitive(primitive, prior_selection, current_instrument=current_instrument)
        if prior_selection.selected_at > min(clocks.decision_cut, clocks.input_known_at):
            raise DependencyUnavailable('prior calendar choice unavailable at cut')
    supports = {s.field: s.status for s in primitive.field_support}
    output = []
    for field in fields:
        if supports[field] != 'observed':
            continue
        definition = 'def:' + content_hash((GENERATOR, DEFINITION, semantic, field, contact_tolerance))
        output.append(Location('prior_' + field, (),
                               line_geometry(primitive, price=Fraction(getattr(primitive, field + '_ticks')),
                                             tolerance=contact_tolerance, definition=definition),
                               (field,)))
    complete = len(output) == len(fields)
    return _seal_locations(LocationSet(primitive, GENERATOR, DEFINITION, tuple(output), clocks, horizon_end,
                       'observed' if complete else 'unavailable_required_fields',
                       candidate_cap, semantic), prior_locations,
        dict(primitive=primitive, clocks=clocks, horizon_end=horizon_end, fields=fields,
             contact_tolerance=contact_tolerance, candidate_cap=candidate_cap,
             prior_selection=prior_selection, current_instrument=current_instrument, semantic=semantic))

