class VenuePath:
    def __init__(self,*,instrument:str,quotes:tuple[VenueQuote,...],trades:tuple[VenueTrade,...],
                 complete_intervals:tuple[tuple[int,int],...],coverage_version:str,max_events:int=2_000_000):
        if not instrument or not coverage_version or len(quotes)+len(trades)>max_events:raise ContractError("bounded source-certified venue path required")
        if any(e.instrument!=instrument for e in (*quotes,*trades)) or len({e.id for e in (*quotes,*trades)})!=len(quotes)+len(trades):raise ContractError("duplicate evidence or mixed raw contracts in venue path")
        if any(a>=b for a,b in complete_intervals) or any(a[1]>b[0] for a,b in zip(complete_intervals,complete_intervals[1:])):raise ContractError("venue coverage intervals overlap or reverse")
        self.instrument=instrument;self.quotes=tuple(sorted(quotes,key=lambda q:(q.event_at,q.sequence if q.sequence is not None else -1,q.id)))
        self.trades=tuple(sorted(trades,key=lambda t:(t.event_at,t.sequence if t.sequence is not None else -1,t.id)))
        self.times=tuple(q.event_at for q in self.quotes);self.trade_times=tuple(t.event_at for t in self.trades)
        self.complete_intervals=complete_intervals;self.coverage_version=coverage_version
        self.information_times=[];self.information_states=[];latest_event=None;current={}
        for known,batch in groupby(sorted(self.quotes,key=lambda q:q.known_at),key=lambda q:q.known_at):
            for q in batch:
                if latest_event is None or q.event_at>latest_event:latest_event=q.event_at;current={q.id:q}
                elif q.event_at==latest_event:current[q.id]=q
            group=tuple(current.values())
            if len(group)>1 and (any(q.sequence is None for q in group) or len({q.sequence for q in group})!=len(group)):
                state=(None,'same-time source quote ordering is unproved')
            else:
                latest=max(group,key=lambda q:q.sequence if q.sequence is not None else -1)
                state=(latest,None) if latest.executable else (None,'invalid/crossed/empty/stale-book or noncontinuous venue quote')
            self.information_times.append(known);self.information_states.append(state)
        self.version=digest({'instrument':instrument,'quotes':quotes,'trades':trades,'coverage':complete_intervals,'version':coverage_version})

    def covered(self,start,end=None):
        timestamp(start);end=start if end is None else timestamp(end)
        if end<start:raise ContractError("coverage interval reversed")
        cursor=start
        for left,right in self.complete_intervals:
            if left<=cursor<right:
                if end<right:return True
                cursor=right
        return False

    def quote_range(self,start,end,*,clock='venue'):
        if clock=='venue':return iter(self.quotes[bisect_left(self.times,start):bisect_right(self.times,end)])
        if clock=='strategy':return (q for q in self.quotes if start<=q.known_at<=end)
        raise ContractError("unknown quote range clock")

    def trade_range(self,start,end):return iter(self.trades[bisect_left(self.trade_times,start):bisect_right(self.trade_times,end)])

    def quote_at(self,at:int,*,clock:str,same_time_ordering:str='ambiguous'):
        timestamp(at)
        if clock not in ('venue','strategy'):raise ContractError("choose venue outcome or actual strategy-information clock")
        if clock=='strategy':
            index=bisect_right(self.information_times,at)-1
            if index<0:return None,'missing strategy quote'
            q,reason=self.information_states[index]
            if q is not None and q.event_at>at:return None,'source event clock ahead of strategy cut; unresolved clock skew'
            return q,reason
        else:
            if not self.covered(at):return None,'venue observation interval not certified'
            end=bisect_left(self.times,at) if same_time_ordering=='order_first' else bisect_right(self.times,at)
            if end==0:return None,'no standing venue quote'
            if same_time_ordering=='ambiguous' and self.quotes[end-1].event_at==at:return None,'order arrival versus same-time venue update is ambiguous'
            last=self.quotes[end-1];start=bisect_left(self.times,last.event_at);tied=list(self.quotes[start:end])
        if len(tied)>1 and (any(q.sequence is None for q in tied) or len({q.sequence for q in tied})!=len(tied)):
            return None,'same-time source quote ordering is unproved'
        quote=max(tied,key=lambda q:q.sequence if q.sequence is not None else -1)
        if clock=='venue':
            segment_start=None;previous_end=None
            for left,right in self.complete_intervals:
                if previous_end!=left:segment_start=left
                if left<=at<right:break
                previous_end=right
            if segment_start is not None and quote.event_at<segment_start:
                return None,'standing quote predates an unobserved interval; explicit book recovery is required'
        return (quote,None) if quote.executable else (None,'invalid/crossed/empty/stale-book or noncontinuous venue quote')

    def marketable(self,*,order_id:str,side:int,arrival_at:int,scenario:FillScenario):
        if not order_id or type(side) is not int or side not in (-1,1) or scenario.quote_coverage_version!=self.coverage_version:raise ContractError("marketable order needs matching coverage and one-unit direction")
        q,reason=self.quote_at(arrival_at,clock='venue',same_time_ordering=scenario.same_time_ordering)
        if q is None:return Fill(order_id,'uncertain',arrival_at,None,0,side,None,scenario.version,reason)
        price=(q.ask if side==1 else q.bid)+side*scenario.impact_ticks
        return Fill(order_id,'filled_under_scenario',arrival_at,price,1,side,q.id,scenario.version,'standing side-correct BBO plus declared adverse impact; historical receipt/queue exactness is not implied')


class CoupledPassiveFills:
    """One shared tape capacity per scenario; process orders in declared priority."""
    def __init__(self,path:VenuePath,scenario:FillScenario):
        if scenario.quote_coverage_version!=path.coverage_version:raise ContractError("scenario coverage mismatch")
        self.path=path;self.scenario=scenario;self.used={};self.orders={};self.last_priority=None

    def evaluate(self,*,order_id:str,side:int,limit_ticks:int,arrival_at:int,cancel_effective_at:int,priority:int):
        args=(side,limit_ticks,arrival_at,cancel_effective_at,priority)
        if order_id in self.orders:
            old,result=self.orders[order_id]
            if old!=args:raise ContractError("hypothetical order ID changed")
            return result
        if side not in (-1,1) or any(type(v) is not int for v in (limit_ticks,arrival_at,cancel_effective_at,priority)) or cancel_effective_at<=arrival_at or self.last_priority is not None and priority<=self.last_priority:
            raise ContractError("passive orders require original expiry and strictly declared shared priority")
        self.last_priority=priority;scenario=self.scenario;path=self.path
        def result(status,at,price=None,event=None,reason=''):
            fill=Fill(order_id,status,at,price,1 if price is not None else 0,side,event,scenario.version,reason);self.orders[order_id]=(args,fill);return fill
        if not path.covered(arrival_at,cancel_effective_at):return result('uncertain',arrival_at,reason='incomplete order-life observation interval')
        standing,reason=path.quote_at(arrival_at,clock='venue',same_time_ordering=scenario.same_time_ordering)
        if standing is None:return result('uncertain',arrival_at,reason=reason)
        if standing and side*((standing.ask if side==1 else standing.bid)-limit_ticks)<=0:
            return result('uncertain',arrival_at,reason='order is marketable at arrival; use registered marketable-limit routing assumptions')
        if scenario.passive_rule=='touch_quote_scenario':
            for q in path.quotes:
                if arrival_at<q.event_at<cancel_effective_at and q.executable and side*((q.ask if side==1 else q.bid)-limit_ticks)<=0:
                    return result('filled_under_scenario',q.event_at,limit_ticks,q.id,'optimistic quote-touch scenario, with no queue-rank evidence')
        else:
            for t in path.trades[bisect_left(path.trade_times,arrival_at):]:
                if t.event_at>cancel_effective_at:break
                if t.aggressor!=-side:continue
                through=side*(t.ticks-limit_ticks)
                if through>0 or scenario.passive_rule=='strict_trade_through' and through==0:continue
                if t.event_at in (arrival_at,cancel_effective_at):
                    if scenario.same_time_ordering=='ambiguous':return result('uncertain',t.event_at,event=t.id,reason='execution versus arrival/cancellation ordering ambiguous')
                    if t.event_at==arrival_at and scenario.same_time_ordering=='venue_first' or t.event_at==cancel_effective_at and scenario.same_time_ordering=='order_first':continue
                if self.used.get(t.id,0)>=t.quantity:continue
                executable_quote,reason=path.quote_at(t.event_at,clock='venue',same_time_ordering='venue_first')
                if executable_quote is None:return result('uncertain',t.event_at,event=t.id,reason=reason)
                self.used[t.id]=self.used.get(t.id,0)+1
                return result('filled_under_scenario',t.event_at,limit_ticks,t.id,'post-arrival execution allocated under declared coupled priority; no exact MBP queue claim')
        return result('no_fill_under_scenario',cancel_effective_at,reason='no eligible execution under this complete-window priority scenario')


def shortfall(*,side:int,decision_mid:Fraction,decision_executable:int,arrival_executable:int,fill_ticks:int):
    if side not in (-1,1) or not isinstance(decision_mid,Fraction):raise ContractError("signed exact decision benchmark required")
    spread=side*(Fraction(decision_executable)-decision_mid);latency=Fraction(side*(arrival_executable-decision_executable));impact=Fraction(side*(fill_ticks-arrival_executable))
    total=side*(Fraction(fill_ticks)-decision_mid)
    if spread+latency+impact!=total:raise ContractError("shortfall attribution does not reconcile")
    return {'total_ticks':total,'decision_spread_ticks':spread,'latency_drift_ticks':latency,'impact_ticks':impact,
            'accounting':'attribution within side-correct fill prices, not three additional cash charges'}

class BracketPlan:
    id:str
    instrument:str
    side:int
    decision_at:int
    worst_entry_ticks:int
    stop_ticks:int
    target_ticks:int
    horizon_end:int
    flatten_send_at:int
    required_flat_at:int
    gap_reserve_usd:Decimal
    geometry_version:str

    def __post_init__(self):
        for at in (self.decision_at,self.horizon_end,self.flatten_send_at,self.required_flat_at):timestamp(at)
        if not self.id or not self.instrument or not self.geometry_version or self.side not in (-1,1) or any(type(x) is not int for x in (self.worst_entry_ticks,self.stop_ticks,self.target_ticks)):
            raise ContractError("bracket requires a frozen one-unit raw-contract plan")
        if self.side*(self.worst_entry_ticks-self.stop_ticks)<=0 or self.side*(self.target_ticks-self.worst_entry_ticks)<=0:
            raise ContractError("stop and target must lie on opposite sides of the frozen entry bound")
        if min(self.horizon_end,self.flatten_send_at)<=self.decision_at or self.required_flat_at<=self.flatten_send_at or not isinstance(self.gap_reserve_usd,Decimal) or not self.gap_reserve_usd.is_finite() or self.gap_reserve_usd<0:
            raise ContractError("bracket has insufficient original horizon or boundary/reserve margin")

    @property
    def version(self):return digest(self)


@dataclass(frozen=True)
class OrderTiming:
    id:str
    outbound_ns:int
    broker_report_ns:int
    native_stop_delay_ns:int
    cancellation_tie:str
    protection_activation:str='synthetic_prestaged_contingent_stop'

    def __post_init__(self):
        if not self.id or any(type(v) is not int or v<0 for v in (self.outbound_ns,self.broker_report_ns,self.native_stop_delay_ns)) or self.cancellation_tie not in ('ambiguous','cancel_first','trigger_first'):
            raise ContractError("explicit routing, broker-report, stop and race assumptions required")
        if self.protection_activation!='synthetic_prestaged_contingent_stop':raise ContractError("unimplemented protection activation requires a separate route")


@dataclass(frozen=True)
class BracketOutcome:
    plan_version:str
    entry:Fill
    exit:Fill|None
    exit_reason:str
    position_known_flat_at:int|None
    gross_usd:Decimal|None
    fees_usd:Decimal
    net_usd:Decimal|None
    minimum_marked_net_usd:Decimal|None
    daily_loss_breach:bool|None
    boundary_met:bool
    unprotected_interval:tuple[int,int]|None
    events:tuple[dict,...]
    timing_version:str
    observation_complete:bool


def reference_bracket(path:VenuePath,plan:BracketPlan,*,terms:FuturesTerms,fees:FeeSchedule,
                      fill_scenario:FillScenario,timing:OrderTiming,prior_day_net:Decimal=Decimal(0),daily_budget:Decimal=Decimal(1000)):
    if plan.instrument!=path.instrument or fill_scenario.fee_version!=fees.version or terms.root not in ('NQ','ES'):
        raise ContractError("bracket, raw venue contract, mini terms and verified fees disagree")
    exposure=Exposure(plan.instrument,terms,plan.side,Ticks(plan.worst_entry_ticks),Ticks(plan.stop_ticks),fees.fee(terms.root,sides=2),plan.gap_reserve_usd)
    verdict=risk_verdict(daily_budget=daily_budget,trading_net_liquidation_pnl=prior_day_net,firm_headroom=None,mutually_possible_exposures=(exposure,),rule_version='synthetic-static-day-start-budget',state_known=True)
    if not verdict.allowed:raise ContractError('bracket refused before entry: '+verdict.reason)
    quote,why=path.quote_at(plan.decision_at,clock='strategy')
    if quote is None:raise ContractError('entry decision lacks an eligible strategy quote: '+why)
    executable=quote.ask if plan.side==1 else quote.bid
    if plan.side*(executable-plan.worst_entry_ticks)>0:raise ContractError("decision quote exceeds frozen entry bound")
    entry_at=plan.decision_at+timing.outbound_ns
    if entry_at>=min(plan.horizon_end,plan.flatten_send_at):raise ContractError("intent expires before modeled venue arrival")
    entry=path.marketable(order_id=plan.id+':entry',side=plan.side,arrival_at=entry_at,scenario=fill_scenario)
    events=[{'kind':'entry_sent','at':plan.decision_at,'plan':plan.version},{'kind':entry.status,'at':entry.at,'price':entry.price_ticks}]
    def finish(exit=None,reason='uncertain_entry',unprotected=None):
        paid=fees.fee(terms.root,sides=2 if exit and exit.quantity else 1) if entry.quantity else Decimal(0)
        if not exit or not exit.quantity:
            return BracketOutcome(plan.version,entry,exit,reason,None,None,paid,None,None,None,False,unprotected,tuple(events),digest(timing),False)
        gross=terms.pnl(Ticks(entry.price_ticks),Ticks(exit.price_ticks),side=plan.side).value;net=sum_usd(gross,negative(paid))
        marks=[sum_usd(prior_day_net,negative(fees.fee(terms.root))),sum_usd(prior_day_net,net)]
        observed=path.covered(entry.at,exit.at)
        standing,standing_reason=path.quote_at(entry.at,clock='venue',same_time_ordering=fill_scenario.same_time_ordering)
        if standing is None:
            observed=False
        else:
            liquidation=standing.bid if plan.side==1 else standing.ask
            marks.append(sum_usd(prior_day_net,terms.pnl(Ticks(entry.price_ticks),Ticks(liquidation),side=plan.side).value,
                                 negative(fees.fee(terms.root))))
        for q in path.quote_range(entry.at,exit.at):
            if entry.at<=q.event_at<=exit.at:
                if not q.executable:observed=False;continue
                liquidation=q.bid if plan.side==1 else q.ask
                marks.append(sum_usd(prior_day_net,terms.pnl(Ticks(entry.price_ticks),Ticks(liquidation),side=plan.side).value,negative(fees.fee(terms.root))))
        minimum=min(marks)
        return BracketOutcome(plan.version,entry,exit,reason,exit.at+timing.broker_report_ns,gross,paid,net,minimum,minimum<=negative(daily_budget) if observed else None,
                              exit.at+timing.broker_report_ns<=plan.required_flat_at,unprotected,tuple(events),digest(timing),observed)
    if not entry.quantity:return finish()
    entry_known=entry.at+timing.broker_report_ns
    local_exit=min(plan.horizon_end,plan.flatten_send_at);reason='deadline' if plan.horizon_end<=plan.flatten_send_at else 'boundary'
    # Check the currently visible standing quote on entry confirmation, then each
    # later publication. A stale older revision does not replace a newer quote.
    cuts=sorted({entry_known,*(q.known_at for q in path.quote_range(entry_known,local_exit,clock='strategy') if q.known_at<local_exit)})
    for cut in cuts:
        if cut>=local_exit:break
        q,_=path.quote_at(cut,clock='strategy')
        if q and plan.side*((q.bid if plan.side==1 else q.ask)-plan.target_ticks)>=0:
            local_exit=cut;reason='target';break
    cancel_at=local_exit+timing.outbound_ns
    stop=None
    for t in path.trade_range(entry.at,cancel_at):
        if plan.side*(t.ticks-plan.stop_ticks)>0:continue
        if t.event_at==entry.at and fill_scenario.same_time_ordering=='ambiguous':
            events.append({'kind':'entry_stop_ordering_ambiguous','at':t.event_at});return finish(reason='uncertain_entry_stop_order')
        if t.event_at==entry.at and fill_scenario.same_time_ordering=='venue_first':continue
        if t.event_at==cancel_at:
            if timing.cancellation_tie=='ambiguous':
                events.append({'kind':'cancel_trigger_race_ambiguous','at':t.event_at});return finish(reason='uncertain_cancel_stop_race')
            if timing.cancellation_tie=='cancel_first':continue
        stop=t;break
    if stop is not None:
        events.append({'kind':'native_stop_triggered','at':stop.event_at,'source':stop.id})
        closing=path.marketable(order_id=plan.id+':stop',side=-plan.side,arrival_at=stop.event_at+timing.native_stop_delay_ns,scenario=fill_scenario)
        events.append({'kind':closing.status,'at':closing.at,'price':closing.price_ticks})
        return finish(closing,'stop')
    events.extend(({'kind':'stop_cancel_sent','at':local_exit,'cause':reason},{'kind':'stop_cancel_effective_under_scenario','at':cancel_at}))
    if not path.covered(entry.at,cancel_at):return finish(reason='uncertain_stop_during_unobserved_interval')
    reconciled_at=cancel_at+timing.broker_report_ns
    exit_at=reconciled_at+timing.outbound_ns
    events.append({'kind':'broker_cancel_and_position_reconciled_under_scenario','at':reconciled_at})
    closing=path.marketable(order_id=plan.id+':full-exit',side=-plan.side,arrival_at=exit_at,scenario=fill_scenario)
    events.append({'kind':closing.status,'at':closing.at,'price':closing.price_ticks})
    return finish(closing,reason,(cancel_at,exit_at))


@dataclass(frozen=True)
class InSetAction:
    id:str
    decision_at:int
    known_flat_at:int
    net:Fraction
    minimum_incremental_mark:Fraction
    required_reserve:Fraction


def exact_static_day_oracle(actions:tuple[InSetAction,...],*,daily_budget:Fraction,maximum_actions:int=10000):
    """Exact foresight upper result ONLY for these fixed outcomes/static rules.

    Higher completed cash dominates at each decision cut for a static day-start
    floor. Trailing-firm floors, business rules and shared scarce-fill changes are
    excluded; they require a larger state and a separately proven algorithm.
    """
    if len(actions)>maximum_actions or len({a.id for a in actions})!=len(actions) or daily_budget<=0:raise ContractError("oracle requires bounded unique finite action set and a static loss budget")
    if any(a.known_flat_at<=a.decision_at or a.required_reserve<0 for a in actions):raise ContractError("invalid occupancy/risk action interval")
    states=[(None,Fraction(0),())]
    for action in sorted(actions,key=lambda a:(a.decision_at,a.id)):
        predecessors=[s for s in states if s[0] is None or s[0]<=action.decision_at]
        best=max(predecessors,key=lambda s:s[1])
        if action.required_reserve>daily_budget+best[1] or best[1]+action.minimum_incremental_mark<=-daily_budget:continue
        states.append((action.known_flat_at,best[1]+action.net,(*best[2],action.id)))
    best=max(states,key=lambda s:s[1])
    return {'best_net':best[1],'selected_actions':best[2],'set_hash':digest(actions),'exact_for_declared_set':True,
            'live_attainable':False,'interpretation':'Foresight optimum for this fixed finite action set, static daily floor, fixed full paths and one-position occupancy only.'}

