class AccountingLedger:
    def __init__(self,path:Path,*,account_id:str,eligible_dates:tuple[str,...],eligibility_version:str,
                 terms:tuple[tuple[str,FuturesTerms],...],fees:FeeSchedule):
        if not account_id or not eligibility_version or not eligible_dates or len(set(eligible_dates))!=len(eligible_dates):raise ContractError("freeze all eligible dates before outcomes, including later flat/outage days")
        for d in eligible_dates:date.fromisoformat(d)
        self.account_id=account_id;self.dates=eligible_dates;self.terms=dict(terms);self.fees=fees;self.journal=Journal(path)
        if len(self.terms)!=len(terms) or any(t.root not in ('NQ','ES') for t in self.terms.values()):raise ContractError("raw NQ/ES mini terms required")
        self.journal.append(key='accounting-contract',kind='accounting_contract',payload={'account_id':account_id,'eligible_dates':eligible_dates,'eligibility_version':eligibility_version,
                           'terms':tuple((id,digest(t)) for id,t in terms),'fee_version':fees.version})

    def fill(self,fill:TradingFill):
        if fill.instrument not in self.terms or fill.trading_date not in self.dates:raise ContractError("fill lies outside the declared raw contract/date universe")
        if fill.fee_version!=self.fees.version or fill.fee!=self.fees.fee(self.terms[fill.instrument].root):raise ContractError("fee differs from the frozen scenario; register changed fees explicitly")
        payload={**asdict(fill),'fee':str(fill.fee)}
        self.journal.append(key='fill:'+fill.execution_id,kind='trading_fill',payload=payload)

    def day_status(self,*,trading_date:str,at:int,status:str,evidence_version:str):
        if trading_date not in self.dates or status not in ('complete','flat','outage','halted','incomplete','boundary_failure') or not evidence_version:raise ContractError("day status cannot remove a predeclared eligible date")
        self.journal.append(key='day:'+trading_date+':'+str(at),kind='day_status',payload={'date':trading_date,'at':at,'status':status,'evidence_version':evidence_version})

    def cash(self,*,id:str,at:int,kind:str,amount:Decimal,evidence_version:str,payout_id:str|None=None):
        usd(amount)
        if not id or not evidence_version or amount<=0 or kind not in ('account_purchase','reset_fee','data_fee','platform_fee','payout_received','refund_received','payout_eligible','payout_requested','payout_approved'):
            raise ContractError("cash/receivable event requires a positive amount and explicit paid/pending category")
        if kind.startswith('payout_') and not payout_id:raise ContractError("payout events require lifecycle identity")
        actual_in=kind in ('payout_received','refund_received');actual_out=kind in ('account_purchase','reset_fee','data_fee','platform_fee')
        cash_change=amount if actual_in else decimal_product(amount,-1) if actual_out else Decimal(0)
        self.journal.append(key='cash:'+id,kind='business_event',payload={'id':id,'at':at,'kind':kind,'amount':str(amount),'payout_id':payout_id,'evidence_version':evidence_version,
                           'entries':{'cash_usd':str(cash_change),'offset_usd':str(decimal_product(cash_change,-1))}})

    def report(self):
        events=self.journal.read();days={d:{'gross':Decimal(0),'fees':Decimal(0),'net':Decimal(0),'fills':0,'status':'unreported'} for d in self.dates}
        position=None;last_at=None;violations=[];cash=Decimal(0);paid=Decimal(0);payouts={};cash_costs=Decimal(0)
        for event in events:
            p=event['payload']
            if event['kind']=='trading_fill':
                if last_at is not None and p['at']<last_at:raise IntegrityError("trading fill sequence regressed; late corrections need a separate explicit ledger version")
                last_at=p['at'];day=days[p['trading_date']];fee=Decimal(p['fee']);day['fees']=decimal_sum(day['fees'],fee);day['fills']+=1
                if position is None:position=p
                elif position['instrument']!=p['instrument'] or position['side']==p['side']:
                    violations.append({'kind':'illegal_add_or_cross_instrument','execution':p['execution_id']});raise IntegrityError("fill ledger reveals unauthorized multiple exposure; preserve broker incident separately")
                else:
                    gross=self.terms[p['instrument']].pnl(Ticks(position['price_ticks']),Ticks(p['price_ticks']),side=position['side']).value
                    day['gross']=decimal_sum(day['gross'],gross)
                    if position['trading_date']!=p['trading_date']:violations.append({'kind':'crossed_trading_day','entry':position['execution_id'],'exit':p['execution_id']})
                    position=None
            elif event['kind']=='day_status':days[p['date']]['status']=p['status']
            elif event['kind']=='business_event':
                amount=Decimal(p['amount']);change=Decimal(p['entries']['cash_usd'])
                if decimal_sum(change,Decimal(p['entries']['offset_usd']))!=0:raise IntegrityError("cash double-entry ledger does not balance")
                cash=decimal_sum(cash,change)
                if change<0:cash_costs=decimal_sum(cash_costs,decimal_product(change,-1))
                if p['kind'].startswith('payout_'):
                    state=payouts.setdefault(p['payout_id'],{'stage':'unreported','recognized_amount':Decimal(0),'received':Decimal(0)})
                    if p['kind']=='payout_received':
                        if state['stage']=='unreported':state['recognized_amount']=amount
                        state['received']=decimal_sum(state['received'],amount);paid=decimal_sum(paid,amount)
                    else:
                        state['stage']=p['kind'];state['recognized_amount']=amount
        total=Decimal(0)
        for d,row in days.items():row['net']=decimal_sum(row['gross'],decimal_product(row['fees'],-1));total=decimal_sum(total,row['net'])
        if position:violations.append({'kind':'unclosed_position','execution':position['execution_id']})
        complete=not violations and all(d['status'] not in ('unreported','incomplete','boundary_failure') for d in days.values())
        mean=Fraction(total)/len(days) if complete else None
        return {'account':self.account_id,'days':days,'eligible_day_count':len(days),'trading_net':total,'mean_net_per_eligible_day':mean,
                'objective_gap':None if mean is None else Fraction(2000)-mean,'complete':complete,'violations':violations,
                'business_net_cash':cash,'paid_business_costs':cash_costs,'received_payouts':paid,
                'eligible_or_pending_payouts':{id:{**p,'unpaid_amount':sum_usd(p['recognized_amount'],negative(p['received']))} for id,p in payouts.items() if p['recognized_amount']>p['received']},
                'payout_receipt_discrepancies':{id:p for id,p in payouts.items() if p['received']>p['recognized_amount']},
                'interpretation':'Spread/latency/impact already represented in actual fill prices; withdrawals and business expenses are separate from trading P&L.'}


@dataclass(frozen=True)
class AccountRules:
    id:str
    basis:str
    evidence_version:str
    initial_equity:Decimal
    drawdown_amount:Decimal
    trailing_mode:str
    floor_cap:Decimal|None
    breach_at_equality:bool
    consistency_fraction:Fraction|None
    minimum_active_days:int

    def __post_init__(self):
        if not self.id or not self.evidence_version or self.basis not in ('synthetic_research_scenario','verified_product_version'):raise ContractError("rules need an explicit synthetic or verified product basis")
        if usd(self.initial_equity)<=0 or usd(self.drawdown_amount)<=0 or self.trailing_mode not in ('static','end_of_day','intraday') or (self.floor_cap is not None and usd(self.floor_cap)<sum_usd(self.initial_equity,negative(self.drawdown_amount))):raise ContractError("invalid explicit drawdown floor rule")
        if self.consistency_fraction is not None and not 0<self.consistency_fraction<=1:raise ContractError("consistency limit must be explicit")
        if type(self.minimum_active_days) is not int or self.minimum_active_days<0:raise ContractError("invalid activity rule")

    @property
    def version(self):return digest(self)


class AccountRuleState:
    def __init__(self,rules:AccountRules):
        self.rules=rules;self.equity=rules.initial_equity;self.high_water=rules.initial_equity;self.floor=sum_usd(rules.initial_equity,negative(rules.drawdown_amount))
        self.pending_withdrawal=Decimal(0);self.breached=False;self.days={};self.path=[]

    def observe(self,*,at:int,trading_date:str,net_liquidation_equity:Decimal,end_of_day:bool=False,day_net:Decimal|None=None,active:bool=False):
        usd(net_liquidation_equity);timestamp(at);date.fromisoformat(trading_date)
        if self.path and at<self.path[-1]['at']:raise ContractError("account rule observation moved backward")
        if end_of_day:
            if day_net is None:raise ContractError("end-of-day consistency requires actual daily net")
            usd(day_net)
            if trading_date in self.days:raise ContractError("day already finalized; append a separately versioned rule correction")
        self.equity=net_liquidation_equity
        # Breach is checked against the previously binding floor before any EOD update.
        available=sum_usd(self.equity,negative(self.pending_withdrawal))
        breach=available<=self.floor if self.rules.breach_at_equality else available<self.floor
        self.breached|=breach
        if self.rules.trailing_mode=='intraday' or self.rules.trailing_mode=='end_of_day' and end_of_day:
            self.high_water=max(self.high_water,self.equity);new=sum_usd(self.high_water,negative(self.rules.drawdown_amount))
            if self.rules.floor_cap is not None:new=min(new,self.rules.floor_cap)
            self.floor=max(self.floor,new)
        if end_of_day:
            self.days[trading_date]={'net':day_net,'active':active}
        row={'at':at,'date':trading_date,'equity':self.equity,'floor':self.floor,'headroom':sum_usd(available,negative(self.floor)),'breached':self.breached,'rule_version':self.rules.version}
        self.path.append(row);return row

    def payout_eligibility(self):
        total=sum((Fraction(d['net']) for d in self.days.values()),Fraction(0));best=max((Fraction(d['net']) for d in self.days.values()),default=Fraction(0))
        consistency=None if total<=0 else max(Fraction(0),best)/total
        active=sum(d['active'] for d in self.days.values())
        allowed=not self.breached and active>=self.rules.minimum_active_days and total>0 and (self.rules.consistency_fraction is None or consistency<=self.rules.consistency_fraction)
        return {'eligible_under_declared_rules':allowed,'active_days':active,'total_net':total,'best_day_over_total_net':consistency,'basis':self.rules.basis,'received_cash':False}

    def reserve_payout(self,amount:Decimal):
        usd(amount)
        if amount<=0 or self.breached or sum_usd(self.equity,negative(self.pending_withdrawal),negative(amount))<=self.floor:raise ContractError("payout reservation would consume binding floor headroom")
        self.pending_withdrawal=decimal_sum(self.pending_withdrawal,amount)

class ObjectTarget:
    id:str
    object_version:str
    cut:int
    end:int
    band:Band
    side:int
    favorable_distance:Fraction
    adverse_distance:Fraction
    observation_process:str
    contact_mode:str='future_contact'

    def __post_init__(self):
        if (any(type(v) is not str or not v for v in (self.id,self.object_version,self.observation_process))
                or self.end<=self.cut or type(self.side) is not int or self.side not in (-1,1)
                or type(self.band) is not Band or self.contact_mode not in ('future_contact','contact_at_cut')):
            raise ContractError("object label requires frozen identity, horizon, process and contact condition")
        if any(not isinstance(v,Fraction) or v<=0 for v in (self.favorable_distance,self.adverse_distance)):raise ContractError("positive frozen departure distances in exact ticks required")
        timestamp(self.cut);timestamp(self.end)

    @property
    def version(self):return digest(self)


def reference_object_label(target:ObjectTarget,*,initial:Fraction,points:tuple[ExactPoint,...],coverage:ObservationWindow):
    if not isinstance(initial,Fraction) or coverage.start!=target.cut or coverage.end>target.end:raise ContractError("initial observation and coverage must belong to the frozen target")
    rows=tuple(sorted(points,key=lambda p:(p.at,p.sequence)))
    if len({(p.at,p.sequence) for p in rows})!=len(rows) or any(not target.cut<p.at<=coverage.end for p in rows):raise ContractError("future object path has duplicate order or out-of-window points")
    if any(a<=p.at<b for p in rows for a,b in coverage.gaps):raise ContractError("observation inside a declared absent interval")
    maturity=max(coverage.certified_through,*(p.known_at for p in rows)) if rows else coverage.certified_through
    complete=coverage.end==target.end and not coverage.gaps
    result={'target_version':target.version,'object_version':target.object_version,'observation_version':coverage.version,
            'observed_end':coverage.end,'maturity_at':maturity,'reach_status':'censored' if not complete else 'no_contact',
            'contact_at':None,'contact_price':None,'gap_crossings':(), 'departure':'censored' if not complete else 'no_contact',
            'first_barrier_at':None,'maximum_favorable_ticks':None,'maximum_adverse_ticks':None,'fixed_end':target.end}
    if target.contact_mode=='contact_at_cut' and not target.band.contains(initial):raise ContractError("contact-conditioned prediction requires observable contact at its own cut")
    if not complete:return _gap_result(result,target,initial,rows,coverage)
    contact=(target.cut,initial) if target.contact_mode=='contact_at_cut' else None
    previous=initial;crosses=[];post=[]
    for at,batch in groupby(rows,key=lambda p:p.at):
        group=tuple(batch)
        if not coverage.source_order_known and len({p.price for p in group})>1:
            relevant=contact is None and any(target.band.contains(p.price) for p in group)
            crosses.extend(p.at for p in group if (previous<target.band.lower and p.price>target.band.upper) or (previous>target.band.upper and p.price<target.band.lower))
            if relevant:
                result.update(reach_status='contact',departure='ambiguous',gap_crossings=tuple(crosses),contact_at=at)
                return _gap_result(result,target,initial,rows,coverage)
            if contact is not None:post.extend(group)
            # Multiple orderings without any contact still cannot invent a touch.
            previous=group[-1].price
            continue
        for p in group:
            if (previous<target.band.lower and p.price>target.band.upper) or (previous>target.band.upper and p.price<target.band.lower):crosses.append(p.at)
            previous=p.price
            if contact is None:
                if target.band.contains(p.price):contact=(p.at,p.price)
            else:post.append(p)
    result['gap_crossings']=tuple(crosses)
    if contact is None:return _gap_result(result,target,initial,rows,coverage)
    result.update(reach_status='contact',contact_at=contact[0],contact_price=contact[1],departure='unresolved')
    deltas=[Fraction(0),*(target.side*(p.price-contact[1]) for p in post)]
    result['maximum_favorable_ticks']=max(deltas);result['maximum_adverse_ticks']=-min(deltas)
    for at,batch in groupby(post,key=lambda p:p.at):
        hits=[]
        for p in batch:
            d=target.side*(p.price-contact[1])
            if d>=target.favorable_distance or d<=-target.adverse_distance:hits.append('favorable_first' if d>=target.favorable_distance else 'adverse_first')
        if hits:
            result.update(departure='ambiguous' if not coverage.source_order_known and len(set(hits))>1 else hits[0],first_barrier_at=at);break
    return _gap_result(result,target,initial,rows,coverage)



def compatible_gap_evidence(target, initial, points, *, source_order_known=True,
                            maximum_states=4096, maximum_batch=8, maximum_transition_work=65536):
    """Enumerate bounded compatible source orders without selecting a last tick."""
    from itertools import permutations
    from math import factorial
    from trading_research.research.temporal_folds import bounded
    if (type(source_order_known) is not bool or type(target) is not ObjectTarget or type(initial) is not Fraction
            or any(type(value) is not int or not 1<=value<=cap for value,cap in
                   ((maximum_states,4096),(maximum_batch,8),(maximum_transition_work,65536)))):
        raise ContractError("explicit finite order evidence required")
    selected=bounded(points,4096,'gap observation')
    if any(type(p) is not ExactPoint for p in selected):
        raise ContractError('exact gap observation points required')
    rows=tuple(sorted(selected,key=lambda p:(p.at,p.sequence)))
    states={(initial,())}
    work=0
    for at,batch in groupby(rows,key=lambda p:p.at):
        group=tuple(batch)
        if len(group)>maximum_batch and not source_order_known:
            raise ContractError("unknown-order batch capacity exceeded")
        charge=len(states)*(1 if source_order_known else factorial(len(group)))*len(group)
        if work+charge>maximum_transition_work:
            raise ContractError('compatible-order transition work capacity exceeded')
        work+=charge
        orders=(group,) if source_order_known else permutations(group)
        following=set()
        for order in orders:
            for previous,crossings in states:
                times=list(crossings)
                for point in order:
                    if ((previous<target.band.lower and point.price>target.band.upper)
                            or (previous>target.band.upper and point.price<target.band.lower)):
                        times.append(at)
                    previous=point.price
                following.add((previous,tuple(times)))
                if len(following)>maximum_states:
                    raise ContractError("compatible-order capacity exceeded")
        states=following
    compatible=tuple(sorted({times for _,times in states}))
    sets=tuple(set(times) for times in compatible)
    return {'compatible_gap_crossing_times':compatible,
            'certain_crossing_time_set':tuple(sorted(set.intersection(*sets))) if sets else (),
            'possible_crossing_time_set':tuple(sorted(set.union(*sets))) if sets else ()}


def _gap_result(result,target,initial,rows,coverage):
    if not coverage.source_order_known and result['reach_status']!='censored':
        evidence=compatible_gap_evidence(target,initial,rows,source_order_known=False)
        result['gap_crossings']=evidence['certain_crossing_time_set']
    return result

class ObservationWindow:
    start: int
    end: int
    certified_through: int
    gaps: tuple[tuple[int, int], ...] = ()
    source_order_known: bool = True
    version: str = ""

    def __post_init__(self) -> None:
        for at in (self.start, self.end, self.certified_through):
            timestamp(at)
        if self.end <= self.start or self.certified_through < self.end or type(self.version) is not str or not self.version:
            raise ContractError("observation window needs bounds, certification clock and version")
        if type(self.source_order_known) is not bool or type(self.gaps) is not tuple:
            raise ContractError("typed immutable observation capability required")
        previous = None
        for gap in self.gaps:
            if type(gap) is not tuple or len(gap) != 2:
                raise ContractError("typed gap interval required")
            a, b = gap
            timestamp(a); timestamp(b)
            if not self.start <= a < b <= self.end or (previous is not None and a < previous):
                raise ContractError("invalid overlapping or unordered gap interval")
            previous = b


@dataclass(frozen=True)
class PathLabel:
    target_signature: str
    observation_version: str
    maturity_at: int
    observed_end: int
    status: str
    terminal_ticks: int | None
    maximum_up_ticks: int | None
    maximum_down_ticks: int | None
    first_barrier: str | None
    first_barrier_at: int | None
    observed_count: int

    @property
    def version(self) -> str:
        return digest(self)


def reference_path_label(target: Target, *, initial: Ticks, points: tuple[PathPoint, ...],
                         coverage: ObservationWindow, up_ticks: int, down_ticks: int) -> PathLabel:
    if any(type(x) is not int or x <= 0 for x in (up_ticks, down_ticks)):
        raise ContractError("positive integral barrier distances required")
    if coverage.start != target.decision_at or coverage.end > target.horizon_end:
        raise ContractError("coverage must start at the frozen cut and cannot extend the target")
    ordered = sorted(points, key=lambda p: (p.at, p.sequence))
    if len({(p.at, p.sequence) for p in ordered}) != len(ordered):
        raise ContractError("duplicate/ambiguous source identity in path")
    if any(not target.decision_at < p.at <= coverage.end for p in ordered):
        raise ContractError("future label path is outside its actual observation window")
    if any(a <= p.at < b for p in ordered for a, b in coverage.gaps):
        raise ContractError("an observed point contradicts a declared unavailable interval")
    maturity = max([coverage.certified_through, *(p.known_at for p in ordered)])
    complete = coverage.end == target.horizon_end and not coverage.gaps
    if not complete:
        # Partial excursions are lower bounds, not observations of the fixed-end target.
        return PathLabel(target.signature, coverage.version, maturity, coverage.end, "censored",
                         None, None, None, None, None, len(ordered))
    deltas = [0, *(p.price.value - initial.value for p in ordered)]
    first, first_at = "neither", None
    for at, group in groupby(ordered, key=lambda p: p.at):
        hits = [("upper" if p.price.value - initial.value >= up_ticks else
                 "lower" if p.price.value - initial.value <= -down_ticks else None) for p in group]
        hits = [h for h in hits if h is not None]
        if hits:
            first_at = at
            first = "ambiguous" if not coverage.source_order_known and len(set(hits)) > 1 else hits[0]
            break
    terminal = deltas[-1] if coverage.source_order_known or len({p.price for p in ordered if p.at == coverage.end}) <= 1 else None
    # Unknown order also makes the last observation ambiguous, even before the endpoint.
    if not coverage.source_order_known and ordered:
        last_prices = {p.price for p in ordered if p.at == ordered[-1].at}
        if len(last_prices) > 1:
            terminal = None
    status = "ambiguous" if first == "ambiguous" or terminal is None else "observed"
    return PathLabel(target.signature, coverage.version, maturity, coverage.end, status,
                     terminal, max(deltas), -min(deltas), first, first_at, len(ordered))


def ohlc_barrier_order(*, initial: Ticks, high: Ticks, low: Ticks,
                       up_ticks: int, down_ticks: int) -> str:
    """OHLC extrema do not identify the ordering when both barriers are reached."""
    if high.value < low.value or up_ticks <= 0 or down_ticks <= 0:
        raise ContractError("invalid OHLC/barriers")
    up = high.value >= initial.value + up_ticks
    down = low.value <= initial.value - down_ticks
    return "ambiguous" if up and down else "upper" if up else "lower" if down else "neither"

