@dataclass(frozen=True)
class CalibratedBinary:
    id:str
    base:BinaryModel|FrequencyModel
    calibration:BinaryModel
    artifact:FittedArtifact
    probability_floor:float
    upstream:tuple[FittedArtifact,...]
    calibration_prediction_manifest_hash:str

    def predict_committed(self, store, commit_ref, node_id, session):
        from trading_research.operations.artifact_graph import serve_bound_model
        return serve_bound_model(self, store, commit_ref, node_id, session)

    @property
    def fit_artifacts(self):
        return (*self.upstream,*artifacts(self.base),*artifacts(self.calibration),self.artifact)

    def predict(self,example:BinaryExample):
        routes={a.id:a.fold_version for a in self.fit_artifacts}
        closure=validate_oof(example.sample,self.id,self.fit_artifacts,fold_version=self.artifact.fold_version,upstream_fold_routes=routes)
        raw,manifest=self.base.predict(example,upstream=self.upstream)
        logit=_logit_example(example,raw,digest(manifest),self.probability_floor)
        calibrated,cal_manifest=self.calibration.predict(logit)
        return calibrated,{'model':self.id,'base_prediction':manifest,'calibration_prediction':cal_manifest,'fit_closure':closure}


def fit_sigmoid_calibration(base:BinaryModel|FrequencyModel,examples,fold:Fold,*,l2_strength:float,
                            probability_floor:float=1e-9,upstream:tuple[FittedArtifact,...]=(),limits=DEFAULT_LIMITS,
                            scope: ResearchScopeV1 | None = None,
                            policy: ResearchPeriodPolicyV1 | None = None,
                            admission: PrimaryAdmissionV1 | None = None):
    if not 0<finite(probability_floor)<.5:raise ContractError("calibration logit floor must be explicit")
    examples=preflight_training(examples,fold,limits=limits,scope=scope,policy=policy,admission=admission)
    training=set(fold.training_ids);converted=[];prediction_manifests=[]
    for example in examples:
        if example.sample.id in training:
            raw,manifest=base.predict(example,upstream=upstream)
            prediction_manifests.append((example.sample.id,manifest,raw))
            converted.append(_logit_example(example,raw,digest(manifest),probability_floor))
        else:
            # No future/evaluation feature or outcome is used in calibration fitting.
            converted.append(BinaryExample(example.sample,(),example.outcome))
    fitted=fit_logistic(converted,fold,('raw_logit',),l2_strength=l2_strength,limits=limits,

class Exposure:
    instrument: str
    terms: FuturesTerms
    side: int
    current_liquidation: Ticks
    stop: Ticks
    remaining_fees: Decimal
    gap_reserve: Decimal

    def __post_init__(self):
        if self.terms.root not in {"NQ", "ES"} or not self.instrument or type(self.side) is not int or self.side not in {-1, 1}:
            raise ContractError("primary exposure must be one outright NQ/ES mini")
        if any(not isinstance(v, Decimal) or not v.is_finite() or v < 0 for v in (self.remaining_fees, self.gap_reserve)):
            raise ContractError("explicit nonnegative remaining fees and gap reserve required")

    @property
    def incremental_reserve(self) -> Decimal:
        adverse_ticks = max(0, self.side * (self.current_liquidation.value - self.stop.value))
        return sum_costs(decimal_product(adverse_ticks, self.terms.tick_size, self.terms.usd_per_point),
                         self.remaining_fees, self.gap_reserve)


@dataclass(frozen=True)
class RiskVerdict:
    allowed: bool
    daily_headroom: Decimal
    firm_headroom: Decimal | None
    incremental_reserve: Decimal
    reason: str
    halt: bool


def risk_verdict(*, daily_budget: Decimal, trading_net_liquidation_pnl: Decimal,
                 firm_headroom: Decimal | None, mutually_possible_exposures: tuple[Exposure, ...],
                 rule_version: str, state_known: bool) -> RiskVerdict:
    for value in (daily_budget, trading_net_liquidation_pnl):
        exact_decimal(value)
    if not Decimal(0) < daily_budget <= Decimal(1000) or not rule_version:
        raise ContractError("frozen day-start loss objective must be positive and at most 1000 USD")
    if firm_headroom is not None:
        exact_decimal(firm_headroom)
    if not isinstance(mutually_possible_exposures, tuple):
        raise ContractError("enumerate feasible simultaneous exposure/race scenarios explicitly")
    daily = sum_costs(daily_budget, trading_net_liquidation_pnl)
    reserve = sum_costs(*(e.incremental_reserve for e in mutually_possible_exposures))
    if not state_known:
        return RiskVerdict(False, daily, firm_headroom, reserve, "unknown account, position, pending order or quote state", True)
    if daily <= 0 or (firm_headroom is not None and firm_headroom <= 0):
        return RiskVerdict(False, daily, firm_headroom, reserve, "day-start or firm headroom exhausted", True)
    if reserve > daily or (firm_headroom is not None and reserve > firm_headroom):
        return RiskVerdict(False, daily, firm_headroom, reserve, "incremental stop/cost/race reserve exceeds headroom", False)
    return RiskVerdict(True, daily, firm_headroom, reserve, "within both frozen limits", False)

class CriticalSnapshot:
    account_id: str
    trading_date: str
    instrument: str
    terms: FuturesTerms
    at: int
    quote_observed_at: int
    feed_liveness_at: int
    broker_observed_at: int
    source_version: str
    bid: Ticks
    ask: Ticks
    position: int
    broker_open_orders: tuple[str, ...]
    trading_net_pnl: Decimal
    daily_budget: Decimal
    firm_headroom: Decimal | None
    rule_version: str
    flatten_at: int
    state_known: bool
    entry_eligible: bool
    halt_reason: str | None = None

    def __post_init__(self):
        date.fromisoformat(self.trading_date)
        for at in (self.at, self.quote_observed_at, self.feed_liveness_at, self.broker_observed_at, self.flatten_at):
            timestamp(at)
        if max(self.quote_observed_at, self.feed_liveness_at, self.broker_observed_at) > self.at:
            raise ContractError("critical snapshot contains a future source observation")
        if (not all((self.account_id, self.instrument, self.source_version, self.rule_version))
                or self.terms.root not in {"NQ", "ES"} or type(self.position) is not int):
            raise ContractError("critical snapshot needs one-account instrument and reconciliation identity")
        # Out-of-limit broker truth is retained and blocks entries; never clamped.
        if not isinstance(self.broker_open_orders, tuple) or len(set(self.broker_open_orders)) != len(self.broker_open_orders):
            raise ContractError("broker order identities must be immutable and unique")
        for value in (self.trading_net_pnl, self.daily_budget, self.firm_headroom):
            if value is not None and (not isinstance(value, Decimal) or not value.is_finite()):
                raise ContractError("exact finite USD accounting required")
        if not Decimal(0) < self.daily_budget <= Decimal(1000):
            raise ContractError("invalid daily budget")
        if type(self.state_known) is not bool or type(self.entry_eligible) is not bool:
            raise ContractError("critical state and entry eligibility require explicit booleans")

    @property
    def version(self):
        return digest(self)

    def record(self):
        return {**asdict(self), "terms": {**asdict(self.terms), "tick_size": str(self.terms.tick_size),
                                           "usd_per_point": str(self.terms.usd_per_point)},
                "bid": self.bid.value, "ask": self.ask.value, "trading_net_pnl": str(self.trading_net_pnl),
                "daily_budget": str(self.daily_budget), "firm_headroom": None if self.firm_headroom is None else str(self.firm_headroom)}

    @classmethod
    def restore(cls, p):
        terms = FuturesTerms(**{**p["terms"], "tick_size": Decimal(p["terms"]["tick_size"]),
                                 "usd_per_point": Decimal(p["terms"]["usd_per_point"])})
        return cls(**{**p, "terms": terms, "bid": Ticks(p["bid"]), "ask": Ticks(p["ask"]),
                      "broker_open_orders": tuple(p["broker_open_orders"]),
                      "trading_net_pnl": Decimal(p["trading_net_pnl"]), "daily_budget": Decimal(p["daily_budget"]),
                      "firm_headroom": None if p["firm_headroom"] is None else Decimal(p["firm_headroom"])})


